        password: sessionConfig.password,
        idleTimeout: 60,
        generateId: () => `clr-${++idCtr}`,
      };
      t.app.get("/clear-err", async (event) => {
        await useSession(event, config);
        await clearSession(event, config);
        throw new HTTPError({ status: 403 });
      });
      t.app.get("/clear-err-ok", async (event) => {
        const session = await useSession(event, config);
        return { id: session.id };
      });

      const res1 = await t.fetch("/clear-err-ok");
      const cookie = res1.headers.getSetCookie().find((c) => c.startsWith("h3-clear-err="))!;

      // t=45s: past the reseal threshold, so `getSession` slides the window — and
      // that reseal must not outlive the clear
      vi.setSystemTime(t0 + 45_000);
      const res2 = await t.fetch("/clear-err", { headers: { Cookie: cookie } });
      expect(res2.status).toBe(403);
      const cleared = res2.headers.getSetCookie().filter((c) => c.startsWith("h3-clear-err="));
      expect(cleared).toHaveLength(1);
      expect(cleared[0]).toContain("Max-Age=0");
    } finally {
      vi.useRealTimers();
    }
  });

  it("applies every chunk of a chunked session cookie to error responses", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      const config: SessionConfig = {
        name: "h3-chunk-err",
        password: sessionConfig.password,
        idleTimeout: 60,
      };
      const big = "x".repeat(5000);
      t.app.get("/chunk-err-ok", async (event) => {
        const session = await useSession(event, config);
        await session.update({ big });
        return "ok";
      });
      t.app.get("/chunk-err", async (event) => {
        await useSession(event, config);
        throw new HTTPError({ status: 418 });
      });

      const res1 = await t.fetch("/chunk-err-ok");
      const setCookies = res1.headers.getSetCookie();
      expect(setCookies.length).toBeGreaterThan(1);
      const cookieHeader = setCookies.map((c) => c.split(";")[0]).join("; ");

      // t=45s: past the reseal threshold, so the errored request reseals
      vi.setSystemTime(t0 + 45_000);
      const res2 = await t.fetch("/chunk-err", { headers: { Cookie: cookieHeader } });
      expect(res2.status).toBe(418);
      expect(
        res2.headers
          .getSetCookie()
          .map((c) => c.split("=")[0])
          .sort(),
      ).toEqual(setCookies.map((c) => c.split("=")[0]).sort());
    } finally {
      vi.useRealTimers();
    }
  });

  it("stores large data in chunks", async () => {
    const token = Array.from({ length: 5000 /* ~4k + one more */ }).fill("x").join("");
    const res = await t.fetch("/", {
      method: "POST",
      headers: { Cookie: cookie },
      body: JSON.stringify({ token }),
    });

    const cookies = res.headers.getSetCookie();
    const cookieNames = cookies.map((c) => c.split("=")[0]);
    expect(cookieNames.length).toBe(3 /* head + 2 */);
    expect(cookieNames).toMatchObject(["h3-test", "h3-test.1", "h3-test.2"]);

    const body = await res.json();
    expect(body.session.data.token).toBe(token);
  });

  it("keeps loaded session data prototype-free", async () => {
    t.app.post("/proto", async (event) => {
      const session = await getSession(event, sessionConfig);
      await updateSession(event, sessionConfig, (await readBody(event)) as any);
      return {
        isAdmin: (session.data as any).isAdmin ?? null,
        inheritsObject: Object.prototype.isPrototypeOf(session.data),
      };
    });
    const seed = await t.fetch("/");
    const seedCookie = seed.headers.getSetCookie()[0].split(";")[0];
    const res = await t.fetch("/proto", {
      method: "POST",
      headers: { Cookie: seedCookie },
      body: '{"__proto__":{"isAdmin":true}}',
    });
    expect(await res.json()).toEqual({ isAdmin: null, inheritsObject: false });
  });

  describe("lazy creation", () => {
    const lazyConfig: SessionConfig = {
      name: "h3-lazy",
      password: "1234567123456712345671234567123456712345671234567",
    };

    it("does not persist a session that is only read", async () => {
      t.app.get("/peek", async (event) => {
        const session = await getSession(event, lazyConfig);
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/peek");
      expect(res.headers.getSetCookie()).toHaveLength(0);
      expect(await res.json()).toMatchObject({ data: {} });
    });

    it("persists on the first write after a read", async () => {
      t.app.get("/login", async (event) => {
        await getSession(event, lazyConfig);
        const session = await updateSession(event, lazyConfig, { user: "alice" });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/login");
      expect(res.headers.getSetCookie()).toHaveLength(1);
      expect(res.headers.getSetCookie()[0]).toContain("h3-lazy=");
      expect(await res.json()).toMatchObject({ data: { user: "alice" } });
    });

    it("seals once when updateSession creates the session", async () => {
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      t.app.get("/seal-count", async (event) => {
        await updateSession(event, lazyConfig, { user: "alice" });
        return "ok";
      });

      deriveBits.mockClear();
      const res = await t.fetch("/seal-count");
      expect(res.headers.getSetCookie()).toHaveLength(1);
      // Two derivations (encryption + integrity) for a single seal
      expect(deriveBits).toHaveBeenCalledTimes(2);
      deriveBits.mockRestore();
    });

    it("useSession still force-inits after a bare getSession", async () => {
      t.app.get("/peek-then-use", async (event) => {
        await getSession(event, lazyConfig); // e.g. auth middleware peeking
        const session = await useSession(event, lazyConfig);
        return { id: session.id };
      });

      const res = await t.fetch("/peek-then-use");
      expect(res.headers.getSetCookie()).toHaveLength(1);
    });

    it("useSession still force-inits when read concurrently", async () => {
      t.app.get("/concurrent", async (event) => {
        const [, session] = await Promise.all([
          getSession(event, lazyConfig),
          useSession(event, lazyConfig),
        ]);
        return { id: session.id };
      });

      const res = await t.fetch("/concurrent");
      expect(res.headers.getSetCookie()).toHaveLength(1);
    });

    it("keeps the session id stable across requests once persisted", async () => {
      t.app.get("/stable", async (event) => {
        const session = await useSession(event, lazyConfig);
        return { id: session.id };
      });

      const res1 = await t.fetch("/stable");
      const setCookie = res1.headers.getSetCookie()[0];
      const { id } = await res1.json();

      const res2 = await t.fetch("/stable", {
        headers: { Cookie: setCookie.split(";")[0] },
      });
      expect(await res2.json()).toMatchObject({ id });
    });
  });

  describe("extraUnsealPasswords", () => {
    const NEW_PASSWORD = "nova-0123456789abcdef0123456789abcdef";
    const OLD_PASSWORD = "antiga-0123456789abcdef0123456789abcd";
    const UNKNOWN_PASSWORD = "desconhecida-0123456789abcdef012345";
    const rotatedConfig: SessionConfig = {
      name: "h3-extra",
      password: NEW_PASSWORD,
      extraUnsealPasswords: [OLD_PASSWORD],
    };
    const legacySealOptions = {
      ...sealDefaults,
      encryption: { ...sealDefaults.encryption, iterations: 1 },
      integrity: { ...sealDefaults.integrity, iterations: 1 },
    };
    const sessionPayload = (overrides: Record<string, unknown> = {}) => ({
      id: "old-id",
      createdAt: Date.now(),
      data: { user: 1 },
      ...overrides,
    });
    const cookieValue = (res: Response, name: string) =>
      decodeURIComponent(res.headers.getSetCookie()[0].match(new RegExp(`${name}=([^;]+)`))![1]);

    it("opens a session sealed with an extra password", async () => {
      const createdAt = Date.now();
      const sealed = await seal(
        sessionPayload({ createdAt }),
        OLD_PASSWORD,
        sealDefaults,
      );
      t.app.get("/extra-read", async (event) => {
        const session = await getSession(event, rotatedConfig);
        return { id: session.id, createdAt: session.createdAt, data: session.data };
      });

      const res = await t.fetch("/extra-read", {
        headers: { Cookie: `h3-extra=${sealed}` },
      });
      expect(await res.json()).toMatchObject({ id: "old-id", createdAt, data: { user: 1 } });
    });

    it("seals writes with password, not with an extra password", async () => {
      t.app.post("/extra-write", async (event) => {
        const session = await updateSession(event, rotatedConfig, { user: 1 });
        return { id: session.id };
      });

      const res = await t.fetch("/extra-write", { method: "POST" });
      const sealed = cookieValue(res, "h3-extra");
      expect(await unseal(sealed, NEW_PASSWORD, sealDefaults)).toMatchObject({
        data: { user: 1 },
      });
      await expect(unseal(sealed, OLD_PASSWORD, sealDefaults)).rejects.toThrow("Bad hmac value");
    });

    it("starts a new session for another password when no extra password is set", async () => {
      const sealed = await seal(sessionPayload(), OLD_PASSWORD, sealDefaults);
      t.app.get("/no-extra", async (event) => {
        const session = await getSession(event, { name: "h3-extra", password: NEW_PASSWORD });
        return { id: session.id, data: session.data };
      });
      t.app.get("/empty-extra", async (event) => {
        const session = await getSession(event, {
          name: "h3-extra",
          password: NEW_PASSWORD,
          extraUnsealPasswords: [],
        });
        return { id: session.id, data: session.data };
      });

      for (const path of ["/no-extra", "/empty-extra"]) {
        const res = await t.fetch(path, { headers: { Cookie: `h3-extra=${sealed}` } });
        expect(res.status).toBe(200);
        expect(await res.json()).toMatchObject({ data: {} });
        expect((await res.clone().json()).id).not.toBe("old-id");
      }
    });

    it("starts a new session for a password that is not in the list", async () => {
      const sealed = await seal(sessionPayload(), UNKNOWN_PASSWORD, sealDefaults);
      t.app.get("/unknown", async (event) => {
        const session = await getSession(event, rotatedConfig);
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/unknown", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(res.status).toBe(200);
      expect(await res.json()).toMatchObject({ data: {} });
    });

    it("rejects an extra-password session past maxAge", async () => {
      const sealed = await seal(
        sessionPayload({ createdAt: Date.now() - 7_200_000 }),
        OLD_PASSWORD,
        sealDefaults,
      );
      t.app.get("/max-age", async (event) => {
        const session = await getSession(event, { ...rotatedConfig, maxAge: 3600 });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/max-age", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toMatchObject({ data: {} });
      expect((await res.clone().json()).id).not.toBe("old-id");
    });

    it("rejects an extra-password session past idleTimeout", async () => {
      const sealed = await seal(
        sessionPayload({ lastSeenAt: Date.now() - 7_200_000 }),
        OLD_PASSWORD,
        sealDefaults,
      );
      t.app.get("/idle", async (event) => {
        const session = await getSession(event, { ...rotatedConfig, idleTimeout: 3600 });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/idle", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toMatchObject({ data: {} });
      expect((await res.clone().json()).id).not.toBe("old-id");
    });

    it("reseals with password when an extra-password session is updated", async () => {
      const sealed = await seal(sessionPayload(), OLD_PASSWORD, sealDefaults);
      t.app.get("/touch", async (event) => {
        const session = await useSession(event, rotatedConfig);
        await session.update({ visto: true } as any);
        return { id: session.id };
      });

      const res = await t.fetch("/touch", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "old-id" });
      const resealed = cookieValue(res, "h3-extra");
      expect(await unseal(resealed, NEW_PASSWORD, sealDefaults)).toMatchObject({
        id: "old-id",
        data: { user: 1, visto: true },
      });
    });

    it("unseals and reseals a legacy session sealed with an extra password", async () => {
      const legacySealed = await seal(sessionPayload(), OLD_PASSWORD, legacySealOptions);
      t.app.get("/legacy-extra", async (event) => {
        const session = await getSession(event, rotatedConfig);
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/legacy-extra", {
        headers: { Cookie: `h3-extra=${legacySealed}` },
      });
      expect(await res.json()).toMatchObject({ id: "old-id", data: { user: 1 } });
      const resealed = cookieValue(res, "h3-extra");
      expect(await unseal(resealed, NEW_PASSWORD, sealDefaults)).toMatchObject({
        id: "old-id",
      });
    });

    it("starts a new session for a legacy extra-password session with legacySealFallback: false", async () => {
      const legacySealed = await seal(sessionPayload(), OLD_PASSWORD, legacySealOptions);
      t.app.get("/legacy-no-fallback", async (event) => {
        const session = await getSession(event, { ...rotatedConfig, legacySealFallback: false });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/legacy-no-fallback", {
        headers: { Cookie: `h3-extra=${legacySealed}` },
      });
      expect((await res.json()).id).not.toBe("old-id");
    });

    it("opens a session header sealed with an extra password", async () => {
      const sealed = await seal(sessionPayload({ id: "header-id" }), OLD_PASSWORD, sealDefaults);
      t.app.get("/header", async (event) => {
        const session = await getSession(event, { ...rotatedConfig, name: "h3-test" });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/header", {
        headers: { "x-h3-test-session": sealed },
      });
      expect(await res.json()).toMatchObject({ id: "header-id", data: { user: 1 } });
    });

    it("unsealSession rejects an expired seal without trying other passwords", async () => {
      const sealed = await seal(sessionPayload(), OLD_PASSWORD, {
        ...sealDefaults,
        ttl: -120_000,
      });
      await expect(unsealSession({} as any, rotatedConfig, sealed)).rejects.toThrow(
        "Expired seal",
      );
    });

    it("unsealSession rejects an unknown password with Bad hmac value", async () => {
      const sealed = await seal(sessionPayload(), UNKNOWN_PASSWORD, sealDefaults);
      await expect(unsealSession({} as any, rotatedConfig, sealed)).rejects.toThrow(
        "Bad hmac value",
      );
    });
  });
});

