        });
        return { id: session.id, data: session.data };
      });

      for (const path of ["/no-extra", "/empty-extra"]) {
        const res = await t.fetch(path, { headers: { Cookie: `h3-extra=${sealed}` } });
        expect(res.status).toBe(200);
        const body = await res.json();
        expect(body).toMatchObject({ data: {} });
        expect(body.id).not.toBe("old-id");
      }
    });

    it("starts a new session for a password that is not in the list", async () => {
      const sealed = await seal(sessionPayload(), UNKNOWN_PASSWORD, sealDefaults);
      t.app.get("/unknown", async (event) => {
        const session = await getSession(event, rotatedConfig);
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/unknown", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(res.status).toBe(200);
      expect(await res.json()).toMatchObject({ data: {} });
    });

    it("rejects an extra-password session past maxAge", async () => {
      const sealed = await seal(
        sessionPayload({ createdAt: Date.now() - 7_200_000 }),
        OLD_PASSWORD,
        sealDefaults,
      );
      t.app.get("/max-age", async (event) => {
        const session = await getSession(event, { ...rotatedConfig, maxAge: 3600 });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/max-age", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toMatchObject({ data: {} });
      expect((await res.clone().json()).id).not.toBe("old-id");
    });

    it("rejects an extra-password session past idleTimeout", async () => {
      const sealed = await seal(
        sessionPayload({ lastSeenAt: Date.now() - 7_200_000 }),
        OLD_PASSWORD,
        sealDefaults,
      );
      t.app.get("/idle", async (event) => {
        const session = await getSession(event, { ...rotatedConfig, idleTimeout: 3600 });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/idle", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toMatchObject({ data: {} });
      expect((await res.clone().json()).id).not.toBe("old-id");
    });

    it("reseals with password when an extra-password session is updated", async () => {
      const sealed = await seal(sessionPayload(), OLD_PASSWORD, sealDefaults);
      t.app.get("/touch", async (event) => {
        const session = await useSession(event, rotatedConfig);
        await session.update({ visto: true } as any);
        return { id: session.id };
      });

      const res = await t.fetch("/touch", { headers: { Cookie: `h3-extra=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "old-id" });
      const resealed = cookieValue(res, "h3-extra");
      expect(await unseal(resealed, NEW_PASSWORD, sealDefaults)).toMatchObject({
        id: "old-id",
        data: { user: 1, visto: true },
      });
    });

    it("unseals and reseals a legacy session sealed with an extra password", async () => {
      const legacySealed = await seal(sessionPayload(), OLD_PASSWORD, legacySealOptions);
      t.app.get("/legacy-extra", async (event) => {
        const session = await getSession(event, rotatedConfig);
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/legacy-extra", {
        headers: { Cookie: `h3-extra=${legacySealed}` },
      });
      expect(await res.json()).toMatchObject({ id: "old-id", data: { user: 1 } });
      const resealed = cookieValue(res, "h3-extra");
      expect(await unseal(resealed, NEW_PASSWORD, sealDefaults)).toMatchObject({
        id: "old-id",
      });
    });

    it("starts a new session for a legacy extra-password session with legacySealFallback: false", async () => {
      const legacySealed = await seal(sessionPayload(), OLD_PASSWORD, legacySealOptions);
      t.app.get("/legacy-no-fallback", async (event) => {
        const session = await getSession(event, { ...rotatedConfig, legacySealFallback: false });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/legacy-no-fallback", {
        headers: { Cookie: `h3-extra=${legacySealed}` },
      });
      expect((await res.json()).id).not.toBe("old-id");
    });

    it("opens a session header sealed with an extra password", async () => {
      const sealed = await seal(sessionPayload({ id: "header-id" }), OLD_PASSWORD, sealDefaults);
      t.app.get("/header", async (event) => {
        const session = await getSession(event, { ...rotatedConfig, name: "h3-test" });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/header", {
        headers: { "x-h3-test-session": sealed },
      });
      expect(await res.json()).toMatchObject({ id: "header-id", data: { user: 1 } });
    });

    it("unsealSession rejects an expired seal without trying other passwords", async () => {
      const sealed = await seal(sessionPayload(), OLD_PASSWORD, {
        ...sealDefaults,
        ttl: -120_000,
      });
      await expect(unsealSession({} as any, rotatedConfig, sealed)).rejects.toThrow(
        "Expired seal",
      );
    });

    it("unsealSession rejects an unknown password with Bad hmac value", async () => {
      const sealed = await seal(sessionPayload(), UNKNOWN_PASSWORD, sealDefaults);
      await expect(unsealSession({} as any, rotatedConfig, sealed)).rejects.toThrow(
        "Bad hmac value",
      );
    });
  });
});

